	/**
	 * Renders one icon as an inline SVG string.
	 *
	 * The return value is already escaped and is safe to echo.
	 *
	 * @param string $slug Icon slug.
	 * @return string Inline SVG markup, or an empty string when unknown.
	 */
	public static function svg( $slug ) {
		$icons = self::all();
		$slug  = sanitize_key( $slug );

		if ( ! isset( $icons[ $slug ] ) ) {
			$slug = 'more';
		}

		if ( ! isset( $icons[ $slug ] ) ) {
			return '';
		}

		$icon = $icons[ $slug ];

		if ( 'stroke' === $icon['type'] ) {
			$path = '<path d="' . esc_attr( $icon['d'] ) . '" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />';
		} else {
			$path = '<path d="' . esc_attr( $icon['d'] ) . '" fill="currentColor" />';
		}

		return '<svg class="ushb-icon" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">' . $path . '</svg>';
	}

	/**
	 * The HTML tags allowed when echoing an icon through wp_kses().
	 *
	 * @return array Allowed tag map.
	 */
	public static function allowed_svg_tags() {
		return array(
			'svg'  => array(
				'class'       => array(),
				'viewbox'     => array(),
				'xmlns'       => array(),
				'aria-hidden' => array(),
				'focusable'   => array(),
			),
			'path' => array(
				'd'               => array(),
				'fill'            => array(),
				'stroke'          => array(),
				'stroke-width'    => array(),
				'stroke-linecap'  => array(),
				'stroke-linejoin' => array(),
			),
		);
	}
